-- =====================================================================
-- 11. Obrigação financeira a partir de venda direta.
--
-- Um único fato comercial gera o título. A politica da organizacao decide
-- QUAL evento é elegível (receivable_trigger), de modo que a mesma venda nunca
-- vira um recebível na aprovação E outro na expedição. O MASTER 013 não emite
-- documento fiscal: o título é a obrigação comercial, não a nota.
-- =====================================================================
CREATE FUNCTION public.sales_receivable_total(_org uuid,_order uuid) RETURNS numeric
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT coalesce(sum(ar.original_amount),0) FROM public.account_receivables ar
 WHERE ar.organization_id=_org AND ar.source_type='SALE' AND ar.source_id=_order::text;
$$;

CREATE FUNCTION public.sales_create_receivables(_org uuid,_order uuid,_trigger text) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE o public.sales_orders; v_base numeric; v_open numeric; v_existing numeric; v_paid numeric;
 v_company uuid; v_terms text; v_credit jsonb; v_n int; v_i int; v_due date; v_terms_id uuid;
BEGIN
 IF _trigger NOT IN ('ON_APPROVAL','ON_DISPATCH') THEN RAISE EXCEPTION 'Gatilho financeiro inválido.'; END IF;
 SELECT * INTO o FROM public.sales_orders WHERE id=_order AND organization_id=_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.'; END IF;
 -- Fonte única: source_type='SALE'. Idempotente pela constraint
 -- UNIQUE(organization_id,source_type,source_id,installment_number).
 IF public.sales_receivable_total(_org,_order)>0 THEN RETURN 0; END IF;
 v_company:=o.company_id;
 v_terms_id:=o.payment_terms_id;
 SELECT name INTO v_terms FROM public.commercial_payment_terms WHERE id=v_terms_id AND organization_id=_org;
 v_credit:=o.credit_check_result;

 -- Base elegível: o que foi expedido menos o que já foi devolvido e recebido.
 -- Na aprovação, a base é o total aprovado.
 IF _trigger='ON_APPROVAL' THEN
  v_base:=o.total_amount;
 ELSE
  v_base:=coalesce((SELECT sum(si.quantity-si.returned_quantity) FROM public.shipment_items si
    JOIN public.shipments s ON s.id=si.shipment_id
    WHERE s.organization_id=_org AND s.sales_order_id=_order AND s.status NOT IN ('DRAFT','CANCELED')),0);
  IF v_base<=0 THEN RETURN 0; END IF;
 END IF;
 -- Já existe título總 total maior que a base? Nada a fazer.
 SELECT coalesce(sum(ar.open_amount),0),coalesce(sum(ar.paid_amount),0) INTO v_open,v_paid
 FROM public.account_receivables ar
 WHERE ar.organization_id=_org AND ar.source_type='SALE' AND ar.source_id=_order::text;
 v_existing:=coalesce(v_open,0)+coalesce(v_paid,0);
 IF v_existing>=v_base THEN RETURN 0; END IF;
 v_base:=round(v_base-v_existing,2);
 IF v_base<=0 THEN RETURN 0; END IF;

 v_n:=cardinality(public.purchasing_split_terms(coalesce(v_terms,'30')));
 v_n:=greatest(1,least(v_n,12));
 FOR v_i IN 1..v_n LOOP
  v_due:=o.order_date+coalesce((public.purchasing_split_terms(coalesce(v_terms,'30')))[v_i],0);
  INSERT INTO public.account_receivables(organization_id,company_id,source_type,source_id,source_status,
    document_number,description,issue_date,due_date,competence_date,original_amount,open_amount,
    currency,status,financial_category_id,cost_center_id,installment_number,total_installments,notes,created_by)
  VALUES(_org,v_company,'SALE',_order::text,'ACTIVE',
    'CLI-'||to_char(o.order_date,'YYYY')||'-'||lpad((o.order_number||'-'||v_i::text),24,'0')||'-'||v_i::text,
    'Pedido '||o.order_number||' — parcela '||v_i||'/'||v_n,
    o.order_date,v_due,o.order_date,
    CASE WHEN v_i<v_n THEN round(v_base/v_n,2) ELSE round(v_base-round(v_base/v_n,2)*(v_n-1),2) END,
    CASE WHEN v_i<v_n THEN round(v_base/v_n,2) ELSE round(v_base-round(v_base/v_n,2)*(v_n-1),2) END,
    o.currency,'OPEN',
    (SELECT fc.id FROM public.financial_categories fc WHERE fc.organization_id=_org AND fc.kind='REVENUE' AND fc.status='ACTIVE' ORDER BY fc.name LIMIT 1),
    null,v_i,v_n,'Origem: venda direta (trigger '||_trigger||')',auth.uid());
 END LOOP;
 PERFORM public.sales_audit(_org,'sales_order.receivable_created','sales_orders',_order,
   jsonb_build_object('trigger',_trigger,'base',v_base,'installments',v_n));
 RETURN v_n;
END;
$$;

-- Esconde o estado do CUSTOMER 360 sem duplicar dado: devolve o que o MASTER 013
-- sabe sobre a venda direta, sempre dos dados oficiais.
CREATE FUNCTION public.sales_company_activity(_org uuid,_company uuid,_limit integer DEFAULT 50) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object(
  'orders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (
    SELECT id,order_number,status,stock_status,fulfillment_status,order_date,expected_delivery_date,
      total_amount,delivered_amount,currency,source_type FROM (
      SELECT o.id,o.order_number,o.status,o.stock_status,o.fulfillment_status,o.order_date,
        o.expected_delivery_date,o.total_amount,o.currency,o.source_type,o.created_at,
        (SELECT coalesce(sum(si.delivered_quantity),0) FROM public.shipment_items si
         JOIN public.shipments s ON s.id=si.shipment_id
         WHERE s.organization_id=_org AND s.sales_order_id=o.id) delivered_amount
      FROM public.sales_orders o WHERE o.organization_id=_org AND o.company_id=_company) x
    LIMIT _limit) x),'[]'::jsonb),
  'shipments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (
    SELECT s.id,s.shipment_number,s.status,s.shipping_method,s.tracking_code,s.dispatched_at,
      s.delivered_at,s.expected_delivery_at,s.created_at
    FROM public.shipments s JOIN public.sales_orders o ON o.id=s.sales_order_id
    WHERE s.organization_id=_org AND o.company_id=_company LIMIT _limit) x),'[]'::jsonb),
  'returns',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM (
    SELECT r.id,r.return_number,r.status,r.reason,r.requested_at,r.received_at,r.financial_action
    FROM public.customer_returns r WHERE r.organization_id=_org AND r.company_id=_company LIMIT _limit) x),'[]'::jsonb));
$$;

